            codePoint = b1;
        } else if ((b1 & 0xE0) == 0xC0) { // two bytes
            if (!bb.hasRemaining()) break;
            int b2 = bb.get() & 0xFF;
            codePoint = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
        } else if ((b1 & 0xF0) == 0xE0) { // three bytes
