@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    List<V> partA = new ArrayList<>();
    List<V> partB = new ArrayList<>();
    for (Map.Entry<String,V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        if (key.startsWith("A")) {
            partA.add(entry.getValue());
        } else if (key.startsWith("B")) {
            partB.add(entry.getValue());
        } else {
            // default to first partition if key format unknown
            partA.add(entry.getValue());
        }
    }
    for (V v : resultMap.values()) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    for (V a : partA) {
        for (V b : partB) {
            target.addEdge(a, b);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (resultMap == null || resultMap.isEmpty()) {
        return;
    }
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    if (n < 2) {
        return;
    }
    for (V v : vertices) {
        target.addVertex(v);
    }
    int mid = n / 2;
    List<V> left = vertices.subList(0, mid);
    List<V> right = vertices.subList(mid, n);
    for (V u : left) {
        for (V v : right) {
            target.addEdge(u, v);
        }
    }
}

public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Partition vertices based on key prefixes ("u"/"l" for left, "v"/"r" for right)
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V vertex = entry.getValue();
        if (key.startsWith("u") || key.startsWith("l")) {
            left.add(vertex);
        } else if (key.startsWith("v") || key.startsWith("r")) {
            right.add(vertex);
        } else {
            // If key does not match convention, distribute evenly
            if (left.size() <= right.size()) {
                left.add(vertex);
            } else {
                right.add(vertex);
            }
        }
    }
    // Add all vertices to the target graph
    for (V v : resultMap.values()) {
        target.addVertex(v);
    }
    // Connect every vertex in left partition to every vertex in right partition
    for (V u : left) {
        for (V w : right) {
            target.addEdge(u, w);
        }
    }
}

