    // encode message into buffer
    schema.writeTo(buffer, message);
    int size = buffer.getTotalSize();
    // write length prefix (varint32)
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeInt32NoTag(size);
    cos.flush();
    // write serialized message bytes
    buffer.writeTo(out);
    buffer.clear();
    return size;
}

