    ParameterizedType pType = (ParameterizedType) genericType;
    Type[] typeArgs = pType.getActualTypeArguments();
    if (typeArgs == null || typeArgs.length == 0) {
        return null;
    }
    // Build a map of type variables to actual types from the target type hierarchy
    java.util.Map<java.lang.reflect.TypeVariable<?>, Type> typeVarMap = new java.util.HashMap<>();
    Class<?> current = targetType;
    while (current != null) {
        Type genericSup = current.getGenericSuperclass();
        if (genericSup instanceof ParameterizedType) {
            ParameterizedType sup = (ParameterizedType) genericSup;
            Type[] actual = sup.getActualTypeArguments();
            java.lang.reflect.TypeVariable<?>[] vars = ((Class<?>) sup.getRawType()).getTypeParameters();
            for (int i = 0; i < vars.length && i < actual.length; i++) {
                if (!typeVarMap.containsKey(vars[i])) {
                    typeVarMap.put(vars[i], actual[i]);
                }
            }
        }
        for (Type genericIface : current.getGenericInterfaces()) {
            if (genericIface instanceof ParameterizedType) {
                ParameterizedType iface = (ParameterizedType) genericIface;
                Type[] actual = iface.getActualTypeArguments();
                java.lang.reflect.TypeVariable<?>[] vars = ((Class<?>) iface.getRawType()).getTypeParameters();
                for (int i = 0; i < vars.length && i < actual.length; i++) {
                    if (!typeVarMap.containsKey(vars[i])) {
                        typeVarMap.put(vars[i], actual[i]);
                    }
                }
            }
        }
        current = current.getSuperclass();
    }
    Class<?>[] result = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        Type arg = typeArgs[i];
        Class<?> resolved = null;
        if (arg instanceof Class<?>) {
            resolved = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            resolved = (Class<?>) ((ParameterizedType) arg).getRawType();
        } else if (arg instanceof java.lang.reflect.TypeVariable<?>) {
            Type mapped = typeVarMap.get(arg);
            if (mapped instanceof Class<?>) {
                resolved = (Class<?>) mapped;
            } else if (mapped instanceof ParameterizedType) {
                resolved = (Class<?>) ((ParameterizedType) mapped).getRawType();
            }
        }
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Class<?> raw = (Class<?>) pt.getRawType();
    if (targetType != null && !targetType.isAssignableFrom(raw)) {
        return null;
    }
    Type[] typeArgs = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        Type t = typeArgs[i];
        if (t instanceof Class<?>) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            result[i] = (Class<?>) ((ParameterizedType) t).getRawType();
        } else if (t instanceof TypeVariable<?>) {
            // Resolve to Object if no bound
            TypeVariable<?> tv = (TypeVariable<?>) t;
            Type[] bounds = tv.getBounds();
            if (bounds.length > 0 && bounds[0] instanceof Class<?>) {
                result[i] = (Class<?>) bounds[0];
            } else {
                result[i] = Object.class;
            }
        } else {
            result[i] = Object.class;
        }
    }
    return result;
}

