public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int start = Math.max(0, index);
    int end = Math.min(str.length(), start + len);
    int pos = start;
    int size = 0;
    while (pos < end) {
        char ch = str.charAt(pos);
        if (Character.isHighSurrogate(ch) && pos + 1 < end && Character.isLowSurrogate(str.charAt(pos + 1))) {
            int codePoint = Character.toCodePoint(ch, str.charAt(pos + 1));
            pos += 2;
            if (codePoint < 0x800) {
                size += 2;
            } else if (codePoint < 0x10000) {
                size += 3;
            } else {
                size += 4;
            }
        } else {
            int codePoint = ch;
            if (codePoint < 0x80) {
                size += 1;
            } else if (codePoint < 0x800) {
                size += 2;
            } else {
                size += 3;
            }
            pos++;
        }
    }
    return size;
}

int computeUTF8Size(final CharSequence str,final int index,final int len){
