    int totalSize = 0;
    while (node != null) {
        byte[] chunk = node.getByteBuffer();          // get the byte array of this segment
        int len = node.getSize();                    // number of valid bytes in this chunk
        out.write(chunk, 0, len);                    // write to the DataOutput
