        AbstractType type = currentFrame[i];
        switch (type.getTag()) {
            case AbstractType.TOP:
                stackMapTableEntries.add((byte) 0);
                break;
            case AbstractType.INTEGER:
                stackMapTableEntries.add((byte) 1);
                break;
            case AbstractType.FLOAT:
                stackMapTableEntries.add((byte) 2);
                break;
            case AbstractType.LONG:
                stackMapTableEntries.add((byte) 3);
                break;
            case AbstractType.DOUBLE:
                stackMapTableEntries.add((byte) 4);
                break;
            case AbstractType.NULL:
                stackMapTableEntries.add((byte) 5);
                break;
            case AbstractType.UNINITIALIZED_THIS:
                stackMapTableEntries.add((byte) 6);
                break;
            case AbstractType.OBJECT:
                stackMapTableEntries.add((byte) 7);
                int cpIndex = type.getCpIndex();
                stackMapTableEntries.add((byte) ((cpIndex >> 8) & 0xFF));
                stackMapTableEntries.add((byte) (cpIndex & 0xFF));
                break;
            case AbstractType.UNINITIALIZED:
                stackMapTableEntries.add((byte) 8);
                int offset = type.getOffset();
                stackMapTableEntries.add((byte) ((offset >> 8) & 0xFF));
                stackMapTableEntries.add((byte) (offset & 0xFF));
                break;
            default:
                throw new IllegalArgumentException("Unknown verification type tag: " + type.getTag());
        }
    }
}

private void putAbstractTypes(final int start, final int end){
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.get(i);
        type.writeVerificationType(stackMapTableEntries);
    }
}

private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.get(i);
        int tag = type.getTag();
        stackMapTableEntries.writeByte(tag);
        if (tag == AbstractType.ITEM_OBJECT) {
            stackMapTableEntries.writeShort(type.getObjectIndex());
        } else if (tag == AbstractType.ITEM_UNINITIALIZED) {
            stackMapTableEntries.writeShort(type.getOffset());
        }
    }
}

