public void readFrom(final InputStream in) throws IOException {
    // Read the entire input stream into a temporary byte array
    ByteArrayOutputStream tempOut = new ByteArrayOutputStream();
    byte[] tmp = new byte[8192];
    int read;
    while ((read = in.read(tmp)) != -1) {
        tempOut.write(tmp, 0, read);
    }
    byte[] data = tempOut.toByteArray();

    // Replace the existing buffer contents
    if (buffer == null || buffer.length != data.length) {
        buffer = new byte[data.length];
    }
    System.arraycopy(data, 0, buffer, 0, data.length);

    // Reset the read pointer to the start of the new buffer
    readPointer = 0;
}

