protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Target type must be Character or primitive char
    if (type != char.class && type != Character.class) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }
    // If already a Character
    if (value instanceof Character) {
        return value;
    }
    // Handle numeric types by casting to char
    if (value instanceof Number) {
        return new Character((char) ((Number) value).intValue());
    }
    // Handle String or CharSequence
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 0) {
            throw new IllegalArgumentException("Cannot convert empty string/character sequence to Character");
        }
        return new Character(cs.charAt(0));
    }
    // Handle char array
    if (value instanceof char[]) {
        char[] arr = (char[]) value;
        if (arr.length == 0) {
            throw new IllegalArgumentException("Cannot convert empty char array to Character");
        }
        return new Character(arr[0]);
    }
    throw new IllegalArgumentException("Unsupported conversion of type " + value.getClass().getName());
}

