public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    // Start from desiredCapacity, adjust to odd if even (except 2)
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    while (true) {
        if (candidate == 2) {
            return 2;
        }
        // Check divisibility by 2
        if (candidate % 2 == 0) {
            candidate++;
            continue;
        }
        boolean isPrime = true;
        int limit = (int) Math.sqrt(candidate);
        for (int i = 3; i <= limit; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // Skip even numbers
    }
}

private static boolean isPrime(int n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if ((n & 1) == 0) return false;
    int limit = (int)Math.sqrt(n);
    for (int i = 3; i <= limit; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) return 2;
    int n = desiredCapacity;
    if ((n & 1) == 0) {
        if (n == 2) return 2;
        n++;
    }
    int limit = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        limit = (int)(desiredCapacity * 1.11);
    }
    for (; n <= limit; n += 2) {
        if (isPrime(n)) return n;
    }
    n = limit + 1;
    if ((n & 1) == 0) n++;
    for (;; n += 2) {
        if (isPrime(n)) return n;
    }
}

