protected int removeUnusedNodes() {
    // Traverse the category tree starting from the root, removing inactive nodes.
    // Returns the number of nodes removed.
    Category root = getRoot(); // Assumes a method getRoot() that returns the root Category
    if (root == null) {
        return 0;
    }

    int removedCount = 0;
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);

    while (!stack.isEmpty()) {
        Category current = stack.pop();
        List<Category> children = current.getChildren(); // Assumes getChildren() returns a mutable list
        if (children != null) {
            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) { // Assumes isActive() indicates node usage
                    it.remove(); // Remove unused node from its parent list
                    removedCount++;
                } else {
                    stack.push(child); // Continue traversal for active children
                }
            }
        }
    }

    return removedCount;
}

