protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0.0);
    }

    Iterator<E> edgeIter = tour.iterator();
    E startEdge = edgeIter.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V current = startVertex;

    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    double weight = 0.0;

    vertexList.add(current);
    Set<E> remaining = new HashSet<>(tour);

    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> remIter = remaining.iterator();
        while (remIter.hasNext()) {
            E e = remIter.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)) {
                edgeList.add(e);
                weight += graph.getEdgeWeight(e);
                current = tgt;
                vertexList.add(current);
                remIter.remove();
                found = true;
                break;
            } else if (tgt.equals(current)) { // handle undirected or reverse edge
                edgeList.add(e);
                weight += graph.getEdgeWeight(e);
                current = src;
                vertexList.add(current);
                remIter.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            // cannot continue forming a consecutive path
            break;
        }
    }

    return new GraphPathImpl<>(graph, vertexList.get(0), current, weight, edgeList, vertexList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    if (edgeList.isEmpty()){
        return new BasicGraphPath<>(graph, vertexList, edgeList, 0.0);
    }
    V current = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(current);
    for (E e : edgeList){
