            int off = offsets[i];
            int nIdx = ((byteCode[off] & 0xFF) << 8) | (byteCode[off + 1] & 0xFF);
            int dIdx = ((byteCode[off + 2] & 0xFF) << 8) | (byteCode[off + 3] & 0xFF);
            if (nIdx == nameIdx && dIdx == descIdx){
                return i;
            }
        }
    }
    int loc = maxPoolSize;
    types[loc] = NAME_TYPE;
    offsets[loc] = byteCode.length;
    byte[] newBytes = java.util.Arrays.copyOf(byteCode, byteCode.length + 4);
    newBytes[newBytes.length - 4] = (byte)(nameIdx >> 8);
    newBytes[newBytes.length - 3] = (byte)(nameIdx & 0xFF);
    newBytes[newBytes.length - 2] = (byte)(descIdx >> 8);
    newBytes[newBytes.length - 1] = (byte)(descIdx & 0xFF);
    byteCode = newBytes;
    maxPoolSize++;
    return loc;
