private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSums = new ArrayList<>(bounds.size());
    long sumAll = 0L;
    for (Integer val : bounds) {
        sumAll += val;
    }

    int n = bounds.size();
    int[] temp = new int[n];
    int running = 0;
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        temp[i] = running;
    }
    for (int i = 0; i < n; i++) {
        suffixSums.add(temp[i]);
    }

    return new Pair<>(suffixSums, sumAll);
}

