    List<Integer> sorted = new ArrayList<>(keys.size());
    for (K k : keys) {
        sorted.add((Integer)k);
    }
    Collections.sort(sorted);
    // remove duplicates to get unique sorted list
    List<Integer> uniq = new ArrayList<>();
    Integer prev = null;
    for (Integer v : sorted) {
        if (!v.equals(prev)) {
            uniq.add(v);
            prev = v;
        }
    }
    // for each key find maximum lower bound
    for (K k : keys) {
        int val = (Integer)k;
        int idx = Collections.binarySearch(uniq, val);
        if (idx < 0) {
            idx = -idx - 1; // insertion point
        }
        int lower = (idx == 0) ? Integer.MIN_VALUE : uniq.get(idx - 1);
        bounds.add(lower);
    }
    return bounds;
}

