    String baseDir;
    int lastSlash = path.lastIndexOf('/');
    if (lastSlash >= 0) {
        // keep the trailing slash for easier concatenation
        baseDir = path.substring(0, lastSlash + 1);
    } else {
        // no slash in the original path; treat as current working directory
        baseDir = "";
    }

    // Combine the base directory with the relative path
    String combined = baseDir + relativePath;

    // Normalize the resulting path, handling "." and ".."
    String[] parts = combined.split("/");
    java.util.LinkedList<String> stack = new java.util.LinkedList<>();
    for (String part : parts) {
        if ("".equals(part) || ".".equals(part)) {
            continue;
        } else if ("..".equals(part)) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.add(part);
        }
    }

    // Reconstruct the normalized path
    StringBuilder sb = new StringBuilder();
    // Preserve leading slash if it existed in the combined path
    if (combined.startsWith("/")) {
        sb.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }

    return sb.toString();
}

