            if(!result.isEmpty()){
                if(result.size()==1&&result.get(0).isEmpty()){
                    // at root, nothing to pop
                }else{
                    result.remove(result.size()-1);
                }
            }
        }else{
            result.add(part);
        }
    }
    StringBuilder sb=new StringBuilder();
    for(int i=0;i<result.size();i++){
        if(i>0)sb.append("/");
        sb.append(result.get(i));
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    boolean isAbsolute = path.startsWith("/");
    String[] baseTokens = path.split("/");
    Deque<String> stack = new ArrayDeque<>();
    int startIdx = 0;
    if (isAbsolute && baseTokens.length > 0 && baseTokens[0].isEmpty()) {
        startIdx = 1;
    }
    for (int i = startIdx; i < baseTokens.length; i++) {
        String part = baseTokens[i];
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else if (!isAbsolute) {
                stack.addLast("..");
            }
        } else {
            stack.addLast(part);
        }
    }
    String[] relTokens = relativePath.split("/");
    for (String part : relTokens) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else if (!isAbsolute) {
                stack.addLast("..");
            }
        } else {
            stack.addLast(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    return sb.toString();
}

